import type { JSX } from "react";
import type * as Stitches from "@stitches/react";
import React from "react";
import { Flex, Text } from "../../atoms";

import {
  ActiveIcon,
  ExitedIcon,
  InProgressIcon,
  NewInviteIcon,
  InActiveIcon,
  UnknownIcon,
} from "../../icons";

export type ClusterStatus =
  | "active"
  | "activating"
  | "exited"
  | "pending_activation"
  | "slashed"
  | "exiting"
  | "incomplete_definition"
  | "awaiting_key_generation"
  | "awaiting_deposits"
  | "exiting_slashed"
  | "unknown";

export type ValidatorStatus =
  // Deposit waiting in the beacon chain's pending_deposits queue (EIP-6110),
  // not yet in the validator registry (obol-api 1.1.2 /state).
  | "pending_deposit"
  | "pending_initialized"
  | "pending_queued"
  | "active_ongoing"
  | "active_exiting"
  | "active_slashed"
  | "exited_unslashed"
  | "exited_slashed"
  | "withdrawal_possible"
  | "withdrawal_done";

export type ClusterAndValidatorStatus = ClusterStatus | ValidatorStatus;
type TextComponentVariants = Stitches.VariantProps<typeof Text>;
// Define the prop types

interface ValidatorStatusProps {
  status: ClusterAndValidatorStatus | undefined | null;
  textVariant?: TextComponentVariants["variant"];
}

// TODO: defined icons for all statuses

