export const MetricValidatorStatus: React.FC<ValidatorStatusProps> = ({
  status,
  textVariant = "h4",
}) => (
  <Flex css={{ gap: "$xs", alignItems: "center" }}>
    {iconMap[status || "pending_activation"]?.icon}
    <Text variant={textVariant} css={{ textTransform: "capitalize" }}>
      {iconMap[status || "pending_activation"]?.text.replace(/_/g, " ")}
    </Text>
  </Flex>
);
